function renderBrazilMap(){
  var mapEl = document.getElementById('rio-brazil-map-wrap');
  if(!mapEl) return;
  var d = IQVIA_NACIONAL.by_uf;

  var PRIO_FILL = {
    CRITICA: {fill:'#ef4444', stroke:'#fca5a5'},
    ALTA:    {fill:'#f97316', stroke:'#fdba74'},
    MEDIA:   {fill:'#eab308', stroke:'#fde047'},
    BAIXA:   {fill:'#3b82f6', stroke:'#93c5fd'}
  };
  var DEFAULT_FILL = '#2a4070';

  var W=560, H=590;
  var svg = '<svg id="rio-brazil-choro-svg" viewBox="0 0 '+W+' '+H+'" '
    +'style="width:100%;height:auto;display:block;border-radius:12px;" xmlns="http://www.w3.org/2000/svg">';

  /* ── DEFS ── */
  svg += '<defs>';
  /* State glow filter */
  svg += '<filter id="rio-state-glow" x="-20%" y="-20%" width="140%" height="140%">'
    +'<feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blur"/>'
    +'<feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>'
  +'</filter>';
  /* Selected glow */
  svg += '<filter id="rio-state-sel" x="-25%" y="-25%" width="150%" height="150%">'
    +'<feGaussianBlur in="SourceGraphic" stdDeviation="5" result="blur"/>'
    +'<feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>'
  +'</filter>';
  svg += '</defs>';

  /* Background — solid, no url() references */
  svg += '<rect width="'+W+'" height="'+H+'" fill="#0b1220" rx="12"/>';

  /* States - sorted so critical ones render on top */
  var prioOrder = {CRITICA:3,ALTA:2,MEDIA:1,BAIXA:0};
  var ufs = Object.keys(BR_REAL_PATHS).sort(function(a,b){
    var pa = (d[a]&&d[a].prio)?prioOrder[d[a].prio]||0:0;
    var pb = (d[b]&&d[b].prio)?prioOrder[d[b].prio]||0:0;
    return pa - pb;
  });

  ufs.forEach(function(uf){
    var ufD  = d[uf];
    var prio = ufD ? ufD.prio : null;
    var pc   = prio ? PRIO_FILL[prio] : null;
    var fill   = pc ? pc.fill : DEFAULT_FILL;
    var stroke = pc ? pc.stroke : '#3d5a80';

    var tooltip = uf + (ufD ? ' — Opp: '+ufD.opp.toLocaleString('pt-BR')+' PDVs' : '');
    svg += '<path id="st-'+uf+'" d="'+BR_REAL_PATHS[uf]+'" '
      +'fill="'+fill+'" fill-opacity="0.9" '
      +'stroke="'+stroke+'" stroke-width="0.6" stroke-linejoin="round" '
      +'onclick="selectBRState(\''+uf+'\')" '
      +'onmouseover="hoverBRState(\''+uf+'\')" onmouseout="unhoverBRState(\''+uf+'\')" '
      +'style="cursor:pointer;transition:fill-opacity 0.15s;">'
      +'<title>'+tooltip+'</title>'
    +'</path>';
  });

  /* State labels — drawn after map renders via setTimeout for getBBox */
  setTimeout(function(){
    ufs.forEach(function(uf){
      var ufD = d[uf];
      var c = getBRStateCenter(uf);
      if(!c) return;
      var small = (uf==='DF'||uf==='SE'||uf==='AL'||uf==='RN'||uf==='PB');
      var fs    = small ? 5 : 7;
      var opp   = ufD ? ufD.opp : 0;
      var oppTxt= opp >= 1000 ? Math.round(opp/1000)+'k' : String(opp);
      var univ  = ufD ? ufD.pdvs : 0;
      var univTxt = univ >= 1000 ? Math.round(univ/1000)+'k' : String(univ);
      var g = document.createElementNS('http://www.w3.org/2000/svg','g');
      g.setAttribute('style','pointer-events:none;user-select:none;');
      /* UF abbreviation */
      var t1 = document.createElementNS('http://www.w3.org/2000/svg','text');
      t1.setAttribute('x', c.x); t1.setAttribute('y', c.y-(small?0:6));
      t1.setAttribute('text-anchor','middle'); t1.setAttribute('dominant-baseline','middle');
      t1.setAttribute('fill','rgba(255,255,255,0.95)');
      t1.setAttribute('font-size', fs+2);
      t1.setAttribute('font-family','Inter,system-ui,sans-serif');
      t1.setAttribute('font-weight','800');
      t1.style.textShadow='0 1px 3px rgba(0,0,0,1)';
      t1.textContent = uf;
      g.appendChild(t1);
      if(!small && ufD){
        /* Opp value */
        var t2 = document.createElementNS('http://www.w3.org/2000/svg','text');
        t2.setAttribute('x', c.x); t2.setAttribute('y', c.y+7);
        t2.setAttribute('text-anchor','middle'); t2.setAttribute('dominant-baseline','middle');
        t2.setAttribute('fill','rgba(255,255,255,0.72)');
        t2.setAttribute('font-size','6');
        t2.setAttribute('font-family','Inter,system-ui,sans-serif');
        t2.setAttribute('font-weight','600');
        t2.textContent = univTxt+' uni · '+oppTxt+' opp';
        g.appendChild(t2);
      }
      var svgEl = document.getElementById('rio-brazil-choro-svg');
      if(svgEl) svgEl.appendChild(g);
    });
  }, 60);

  /* Legend */
  var items=[{l:'CRÍTICA',p:'CRITICA'},{l:'ALTA',p:'ALTA'},{l:'MÉDIA',p:'MEDIA'},{l:'BAIXA',p:'BAIXA'}];
  var lx=10, ly=H-26;
  svg += '<rect x="'+lx+'" y="'+(ly-6)+'" width="250" height="22" rx="6" '
    +'fill="rgba(0,0,0,0.55)" stroke="rgba(255,255,255,0.10)" stroke-width="0.5"/>';
  items.forEach(function(it,i){
    var c = PRIO_FILL[it.p];
    svg += '<rect x="'+(lx+8+i*61)+'" y="'+(ly-1)+'" width="10" height="10" rx="2" fill="'+c.fill+'"/>';
    svg += '<text x="'+(lx+21+i*61)+'" y="'+(ly+8)+'" fill="rgba(180,190,210,0.8)" '
      +'font-size="7.5" font-family="Inter,system-ui,sans-serif" font-weight="600">'+it.l+'</text>';
  });

  svg += '</svg>';
  mapEl.innerHTML = svg;
}

function getBRStateCenter(uf){
  var el = document.getElementById('st-'+uf);
  if(!el) return null;
  try {
    var bb = el.getBBox();
    return {x: Math.round(bb.x + bb.width/2), y: Math.round(bb.y + bb.height/2)};
  } catch(e){ return null; }
}

function hoverBRState(uf){
  if(uf === _selectedUF) return;
  var el = document.getElementById('st-'+uf);
  if(el){ el.setAttribute('fill-opacity','1'); el.setAttribute('stroke-width','1.5'); el.setAttribute('filter','url(#rio-state-glow)'); }
}
function unhoverBRState(uf){
  if(uf === _selectedUF) return;
  var el = document.getElementById('st-'+uf);
  if(el){ el.setAttribute('fill-opacity','1'); el.setAttribute('stroke-width','0.6'); el.removeAttribute('filter'); }
}

function selectBRState(uf){
  /* Deselect previous */
  if(_selectedUF && _selectedUF !== uf){
    var prev = document.getElementById('st-'+_selectedUF);
    if(prev){ prev.setAttribute('stroke-width','0.6'); prev.removeAttribute('filter'); prev.setAttribute('fill-opacity','1'); }
  }
  _selectedUF = uf;
  /* Highlight selected */
  var el = document.getElementById('st-'+uf);
  if(el){ el.setAttribute('stroke','#ffffff'); el.setAttribute('stroke-width','2'); el.setAttribute('filter','url(#rio-state-sel)'); }
  renderStateDetail(uf);
}

/* ── Mesoregion assignment by lat/lon ── */
function getStateMeso(uf, lat, lon) {
  var SP=function(la,lo){
    if(lo<-50.5) return 'Pres. Prudente / Araçatuba';
    if(lo<-49&&la>-20.5) return 'São José do Rio Preto';
    if(lo<-49&&la<=-20.5) return 'Bauru / Marília / Assis';
    if(lo>=-47&&la<=-22.5&&la>-24) return 'Grande SP / ABC';
    if(lo>=-47&&la<=-24) return 'Litoral / Vale do Ribeira';
    if(lo>=-49&&la>-21&&lo<-47) return 'Ribeirão Preto / Franca';
    if(lo>=-47&&la>-23&&la<=-22) return 'Vale do Paraíba';
    if(lo<-47&&la<=-21&&la>-23) return 'Campinas / Sorocaba';
    return 'Itapetininga / Interior Central';
  };
  var MG=function(la,lo){
    if(la>-15.5) return 'Norte de Minas';
    if(la>-17.5&&lo<-45.5) return 'Noroeste de Minas';
    if(lo<-47.5) return 'Triângulo / Alto Paranaíba';
    if(la>-17&&lo>-42.5) return 'Vale do Mucuri / Jequitinhonha';
    if(la>-19&&lo>=-43.5&&lo<-41) return 'Vale do Rio Doce';
    if(lo>=-45&&lo<-43&&la>-20.5) return 'Metropolitana de BH';
    if(la<=-20.5&&lo>=-44&&lo<-42) return 'Campo das Vertentes / Zona da Mata';
    if(la<=-21&&lo<-45.5) return 'Sul / Sudoeste de Minas';
    if(la>-20.5&&lo>=-47.5&&lo<-45) return 'Oeste / Central Mineira';
    return 'Zona da Mata / Leste';
  };
  var RJ=function(la,lo){
    if(lo<-43&&la>-22.5) return 'Norte / Noroeste Fluminense';
    if(la>-22.8&&lo>=-43.8) return 'Grande Rio';
    if(lo>=-42&&la<-22.8) return 'Baixadas Litorâneas / Sul';
    return 'Sul Fluminense / Médio Paraíba';
  };
  var BA=function(la,lo){
    if(lo<-44) return 'Extremo Oeste / Vale São Francisco';
    if(la>-11.5&&lo>=-44) return 'Norte da Bahia';
    if(la>-13&&lo>-40) return 'Nordeste da Bahia';
    if(la>-14&&lo>=-40&&lo<-38.5) return 'Centro-Norte / Sisal';
    if(la>=-16&&la<=-14&&lo<-40) return 'Centro-Leste / Chapada';
    if(lo>-38.5&&la>-13.5) return 'Metropolitana de Salvador / Litoral';
    if(la>-16&&lo>=-38.5) return 'Litoral Sul / Recôncavo';
    return 'Sul da Bahia';
  };
  var PE=function(la,lo){
    if(lo<-38) return 'Sertão / São Francisco';
    if(lo<-36.5) return 'Agreste';
    if(la>-8.5) return 'Zona da Mata Norte';
    return 'Zona da Mata Sul / RMR';
  };
  var PR=function(la,lo){
    if(lo<-52) return 'Oeste do Paraná';
    if(lo<-50&&la>-23.5) return 'Norte Central / Noroeste';
    if(lo<-50&&la<=-23.5) return 'Campos Gerais / Sudoeste';
    if(la>-24.5&&lo>=-50) return 'Norte Pioneiro';
    if(la>-25.5&&lo>=-50) return 'Curitiba / RMC';
    return 'Litoral / Sul do Paraná';
  };
  var RS=function(la,lo){
    if(lo<-53&&la>-29) return 'Noroeste / Missões';
    if(lo<-53&&la<=-29) return 'Sudoeste Gaúcho';
    if(la>-28.5&&lo>=-53) return 'Norte Gaúcho / Serra';
    if(la>-30.5&&lo>=-50) return 'Litoral Norte';
    return 'Metropolitana POA / Sul';
  };
  var SC=function(la,lo){
    if(lo<-51) return 'Oeste Catarinense';
    if(lo<-49.5&&la>-27) return 'Planalto Serrano / Norte';
    if(lo>=-49.5&&la>-27) return 'Norte Catarinense';
    return 'Grande Florianópolis / Sul';
  };
  var GO=function(la,lo){
    if(la>-14) return 'Norte de Goiás';
    if(lo<-50&&la<=-14) return 'Noroeste / Sudoeste';
    if(lo>=-48.5&&la>-17) return 'Entorno do DF / Leste';
    return 'Centro / Sul de Goiás';
  };
  var CE=function(la,lo){
    if(lo<-39.5) return 'Sertão / Noroeste';
    if(la>-5) return 'Norte / Litoral';
    if(lo>-38.5) return 'Fortaleza / Litoral Leste';
    return 'Centro-Sul Cearense';
  };
  var MA=function(la,lo){
    if(lo<-44.5) return 'Oeste Maranhense';
    if(la>-3.5) return 'Norte Maranhense';
    if(lo>-43) return 'Leste Maranhense';
    return 'Centro Maranhense';
  };
  var PA=function(la,lo){
    if(lo<-52) return 'Sudoeste Paraense';
    if(la>-3) return 'Nordeste / Marajó';
    return 'Sudeste Paraense';
  };
  var spec={'SP':SP,'MG':MG,'RJ':RJ,'BA':BA,'PE':PE,'PR':PR,'RS':RS,'SC':SC,'GO':GO,'CE':CE,'MA':MA,'PA':PA};
  if(spec[uf]) return spec[uf](lat,lon);
  var b = typeof ED_BOUNDS!=='undefined'?ED_BOUNDS[uf]:null;
  if(!b) return 'Geral';
  var latR=b[1]-b[0], lonR=b[3]-b[2];
  var t1=b[0]+latR*0.33, t2=b[0]+latR*0.67;
  var ns=lat>t2?'Norte':lat>t1?'Centro':'Sul';
  if(lonR>4){ var lm=b[2]+lonR*0.5; return ns+(lon>lm?' Leste':' Oeste'); }
  return ns;
}

function renderStateDetail(uf){
  var panel = document.getElementById('rio-brazil-state-panel');
  if(!panel) return;
  var d = IQVIA_NACIONAL.by_uf[uf];
  if(!d){
    panel.innerHTML='<div style="color:#94A3B8;padding:24px;text-align:center;font-size:12px;">Sem dados para '+uf+'</div>';
    return;
  }

  panel.style.alignItems = 'flex-start';
  panel.style.justifyContent = 'flex-start';

  var pct_scj  = Math.round(d.scj26/d.pdvs*100);
  var pct_opp  = 100 - pct_scj;
  var areas    = STATE_AREAS[uf]||[{a:'Capital',p:0.40},{a:'Interior',p:0.60}];
  var PCOLS    = {CRITICA:'#ef4444',ALTA:'#f97316',MEDIA:'#fbbf24',BAIXA:'#64748b'};
  var PLBLS    = {CRITICA:'🔴 PRIORIDADE CRÍTICA',ALTA:'🟠 PRIORIDADE ALTA',MEDIA:'🟡 PRIORIDADE MÉDIA',BAIXA:'⚪ PRIORIDADE BAIXA'};
  var prioCol  = PCOLS[d.prio]||'#64748b';

  panel.style.alignItems = 'flex-start'; panel.style.justifyContent = 'flex-start';
  var panelH = panel.offsetHeight || 600;
  var html = '<div style="animation:fadeIn 0.2s ease;width:100%;display:flex;flex-direction:column;justify-content:space-between;min-height:'+(panelH-36)+'px;">';

  /* Header */
  html += '<div style="background:linear-gradient(135deg,rgba('+hexToRgb(prioCol)+',0.18) 0%,rgba(0,0,0,0) 100%);'
    +'border-left:4px solid '+prioCol+';padding:12px 16px;border-radius:0 10px 10px 0;margin-bottom:14px;">';
  html += '<div style="font-size:13px;font-weight:700;letter-spacing:0.12em;color:'+prioCol+';margin-bottom:5px;">'+( PLBLS[d.prio]||d.prio )+'</div>';
  html += '<div style="font-size:26px;font-weight:800;color:#e2e8f0;line-height:1.1;">'
    +STATE_NAMES[uf]
    +'<span style="font-size:16px;color:#94A3B8;font-weight:500;margin-left:8px;">'+uf+'</span></div>';
  html += '</div>';

  /* KPI row — equal height cards */
  html += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px;">';
  [{l:'UNIVERSE',v:d.pdvs.toLocaleString('pt-BR'),sub:'PDVs mapeados',c:'#67e8f9',icon:'🏪'},
   {l:'SCJ FY26', v:d.scj26.toLocaleString('pt-BR'),sub:pct_scj+'% penetração',c:'#34d399',icon:'✅'},
   {l:'OPORTUNIDADE',v:(d.pdvs-d.scj26).toLocaleString('pt-BR'),sub:pct_opp+'% do universe',c:'#06b6d4',icon:'🎯'}
  ].forEach(function(k){
    html += '<div style="background:rgba(0,0,0,0.30);border-radius:10px;padding:14px 10px;'
      +'border-top:3px solid '+k.c+';text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:90px;">'
      +'<div style="font-size:18px;margin-bottom:3px;">'+k.icon+'</div>'
      +'<div style="font-size:12px;font-weight:700;letter-spacing:0.06em;color:rgba(139,149,168,0.85);margin-bottom:4px;">'+k.l+'</div>'
      +'<div style="font-size:24px;font-weight:800;color:'+k.c+';">'+k.v+'</div>'
      +'<div style="font-size:12px;color:rgba(255,255,255,0.32);margin-top:2px;">'+k.sub+'</div>'
    +'</div>';
  });
  html += '</div>';

  /* Penetração bar */
  html += '<div style="margin-bottom:16px;">';
  html += '<div style="display:flex;justify-content:space-between;font-size:12px;color:#94A3B8;margin-bottom:6px;">'
    +'<span style="font-weight:600;">Penetração SCJ vs Oportunidade</span>'
    +'<span style="color:rgba(255,255,255,0.45);font-weight:700;">'+pct_scj+'% atingido</span>'
  +'</div>';
  html += '<div style="display:flex;height:22px;border-radius:7px;overflow:hidden;gap:2px;">'
    +'<div style="width:'+pct_scj+'%;background:linear-gradient(90deg,rgba(52,211,153,0.85),rgba(16,185,129,0.95));'
    +'display:flex;align-items:center;justify-content:center;min-width:36px;">'
    +'<span style="font-size:13px;font-weight:800;color:#0a2018;">SCJ '+pct_scj+'%</span></div>'
    +'<div style="flex:1;background:linear-gradient(90deg,rgba(6,182,212,0.65),rgba(220,38,38,0.55));'
    +'display:flex;align-items:center;justify-content:center;">'
    +'<span style="font-size:13px;font-weight:700;color:rgba(255,255,255,0.85);">OPP '+(100-pct_scj)+'%</span></div>'
  +'</div></div>';

  /* ── City table by mesoregion ── */
  var PCITYCOLS=['#ef4444','#f97316','#eab308','#64748b'];
  var PCITYLBLS=['CRÍTICA','ALTA','MÉDIA','BAIXA'];

  /* Build city list from ED_CITIES_RAW */
  var ufIdx = (typeof ED_UFS!=='undefined') ? ED_UFS.indexOf(uf) : -1;
  var cities = [];
  if(ufIdx>=0 && typeof ED_CITIES_RAW!=='undefined'){
    ED_CITIES_RAW.forEach(function(c){
      if(c[0]===ufIdx) cities.push({
        name: String(c[1]).replace(/ - [A-Z]{2}$/,''),
        pdvs:c[2], scj:c[3], opp:c[4], pct:Number(c[5]), prio:c[6], lat:c[7], lon:c[8]
      });
    });
    cities.sort(function(a,b){return b.opp-a.opp;});
  }

  /* Group cities by mesoregion */
  var mesoMap={}, mesoOrder=[];
  cities.forEach(function(city){
    var m = (typeof getStateMeso==='function') ? getStateMeso(uf,city.lat,city.lon) : 'Geral';
    if(!mesoMap[m]){mesoMap[m]=[];mesoOrder.push(m);}
    mesoMap[m].push(city);
  });
  mesoOrder.sort(function(a,b){
    var oa=mesoMap[a].reduce(function(s,c){return s+c.opp;},0);
    var ob=mesoMap[b].reduce(function(s,c){return s+c.opp;},0);
    return ob-oa;
  });

  /* City table header */
  html += '<div style="font-size:10px;font-weight:700;letter-spacing:0.09em;color:rgba(139,149,168,0.7);margin-bottom:6px;margin-top:4px;">🏙 CIDADES · POSITIVAÇÃO vs OPORTUNIDADE'
    +(cities.length?' <span style=\'font-weight:400;color:#3d4451;\'>('+cities.length+' cidades)</span>':'')+'</div>';

  /* Column header bar */
  html += '<div style="display:grid;grid-template-columns:1fr 48px 70px 50px 50px;gap:0;'
    +'padding:4px 10px;background:#08111e;border-radius:6px 6px 0 0;'
    +'font-size:9px;font-weight:700;letter-spacing:0.06em;color:#4a5568;text-transform:uppercase;">'
    +'<div>Cidade</div>'
    +'<div style="text-align:right;">Univ.</div>'
    +'<div style="text-align:right;">Positiv.</div>'
    +'<div style="text-align:right;">Opp</div>'
    +'<div style="text-align:right;">Prio</div>'
    +'</div>';

  /* Scrollable body */
  html += '<div style="overflow-y:auto;max-height:310px;border-radius:0 0 8px 8px;'
    +'background:rgba(0,0,0,0.18);border:1px solid rgba(255,255,255,0.04);border-top:none;">';

  mesoOrder.forEach(function(meso){
    var grp = mesoMap[meso];
    var totalOpp  = grp.reduce(function(s,c){return s+c.opp;},0);
    var totalPdvs = grp.reduce(function(s,c){return s+c.pdvs;},0);
    var totalScj  = grp.reduce(function(s,c){return s+c.scj;},0);
    var grpPct    = totalPdvs>0 ? (totalScj/totalPdvs*100).toFixed(0) : 0;

    /* Mesoregion header row */
    html += '<div style="display:grid;grid-template-columns:1fr auto;gap:4px;align-items:center;'
      +'padding:5px 10px;background:#0b1525;'
      +'border-top:1px solid rgba(6,182,212,0.18);border-bottom:1px solid rgba(6,182,212,0.25);position:sticky;top:0;z-index:2;">'
      +'<span style="font-size:9px;font-weight:800;color:#67e8f9;letter-spacing:0.07em;">📍 '+meso.toUpperCase()+'</span>'
      +'<span style="font-size:9px;color:#4a6b65;white-space:nowrap;">'
        +totalPdvs.toLocaleString('pt-BR')+' PDVs &nbsp;·&nbsp; '
        +'<span style=\'color:#34d399;font-weight:700;\'>'+grpPct+'%</span> positiv.'
        +' &nbsp;·&nbsp; <span style=\'color:#06b6d4;font-weight:700;\'>'+totalOpp.toLocaleString('pt-BR')+' opp</span>'
      +'</span>'
    +'</div>';

    /* City rows (top 25 per group) */
    grp.slice(0,25).forEach(function(city){
      var pc = PCITYCOLS[city.prio]||'#64748b';
      var pl = PCITYLBLS[city.prio]||'';
      html += '<div style="display:grid;grid-template-columns:1fr 48px 70px 50px 50px;gap:0;'
        +'padding:4px 10px;border-bottom:1px solid rgba(255,255,255,0.025);'
        +'align-items:center;font-size:10px;">'
        +'<div style="color:#c8d0dc;font-weight:500;white-space:nowrap;overflow:hidden;'
          +'text-overflow:ellipsis;" title="'+city.name+'">'+city.name+'</div>'
        +'<div style="text-align:right;color:#94A3B8;">'+city.pdvs.toLocaleString('pt-BR')+'</div>'
        +'<div style="text-align:right;">'
          +'<span style=\'color:#34d399;font-weight:700;\'>'+city.scj.toLocaleString('pt-BR')+'</span>'
          +'<span style=\'font-size:8px;color:#3d6b63;\'>  ('+city.pct.toFixed(0)+'%)</span>'
        +'</div>'
        +'<div style="text-align:right;color:#06b6d4;font-weight:700;">'+city.opp.toLocaleString('pt-BR')+'</div>'
        +'<div style="text-align:right;">'
          +'<span style=\'font-size:8px;font-weight:700;padding:1px 4px;border-radius:3px;'
          +'background:'+pc+'22;color:'+pc+';\'>'
          +pl+'</span>'
        +'</div>'
      +'</div>';
    });
    if(grp.length>25){
      html += '<div style="padding:3px 10px;font-size:9px;color:#3d4451;text-align:center;'
        +'background:rgba(0,0,0,0.15);">+ '+(grp.length-25)+' cidades adicionais</div>';
    }
  });

  if(cities.length===0){
    html += '<div style="padding:20px;text-align:center;color:#3d4451;font-size:12px;">Sem dados de cidades para '+uf+'</div>';
  }

  html += '</div>'; /* close scrollable */

  /* Bottom strip: Reconquista + Novos (compact) */
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px;">'
    +'<div style="background:rgba(45,212,191,0.08);border-radius:8px;padding:10px;'
      +'border:0.5px solid rgba(45,212,191,0.25);text-align:center;">'
      +'<div style="font-size:10px;color:#94A3B8;letter-spacing:0.06em;font-weight:700;margin-bottom:3px;">♻️ RECONQUISTA</div>'
      +'<div style="font-size:20px;font-weight:800;color:#2dd4bf;">'+d.recon.toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:10px;color:rgba(255,255,255,0.25);">PDVs</div>'
    +'</div>'
    +'<div style="background:rgba(251,191,36,0.08);border-radius:8px;padding:10px;'
      +'border:0.5px solid rgba(251,191,36,0.25);text-align:center;">'
      +'<div style="font-size:10px;color:#94A3B8;letter-spacing:0.06em;font-weight:700;margin-bottom:3px;">🆕 NOVOS CLIENTES</div>'
      +'<div style="font-size:20px;font-weight:800;color:#fbbf24;">'+d.novos.toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:10px;color:rgba(255,255,255,0.25);">PDVs</div>'
    +'</div>'
  +'</div>';

  html += '</div>'; /* close outer flex */

  /* ── Ver Municípios button ── */
  html += '<div style="padding:10px 2px 4px;margin-top:10px;border-top:0.5px solid rgba(245,225,164,0.08);">'
    +'<button onclick="(function(){'
      +'switchIQVIAMapTab(\'cidades\',document.getElementById(\'rio-iqvia-tab-cidades\'));'
      +'setTimeout(function(){edDrillDownState(\''+uf+'\');},350);'
    +'})()" '
    +'style="width:100%;background:linear-gradient(135deg,rgba(6,182,212,0.18) 0%,rgba(6,182,212,0.08) 100%);'
    +'border:1px solid rgba(6,182,212,0.4);color:#67e8f9;padding:11px;border-radius:9px;'
    +'cursor:pointer;font-size:11px;font-weight:700;letter-spacing:0.05em;'
    +'transition:.2s;display:flex;align-items:center;justify-content:center;gap:7px;">'
    +'<span style="font-size:14px;">🗺</span>'
    +'Ver Municípios de '+( STATE_NAMES&&STATE_NAMES[uf]?STATE_NAMES[uf]:uf )
    +'</button>'
  +'</div>';

  panel.innerHTML = html;
}

function hexToRgb(hex){
  var r=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return r ? parseInt(r[1],16)+','+parseInt(r[2],16)+','+parseInt(r[3],16) : '0,0,0';
}

